export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) throw new TypeError('intervals must be an array');

  const pairs = [];
  for (const pair of intervals) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('every interval must be an array of exactly two numbers');
    }
    const [start, end] = pair;
    if (typeof start !== 'number' || !Number.isFinite(start)) {
      throw new TypeError('every bound must be a finite number');
    }
    if (typeof end !== 'number' || !Number.isFinite(end)) {
      throw new TypeError('every bound must be a finite number');
    }
    if (start > end) throw new RangeError('start must not be greater than end');
    pairs.push([start, end]);
  }

  pairs.sort((x, y) => (x[0] - y[0]) || (x[1] - y[1]));

  const out = [];
  for (const [start, end] of pairs) {
    const last = out[out.length - 1];
    if (last !== undefined && start <= last[1]) {
      if (end > last[1]) last[1] = end;
      continue;
    }
    out.push([start, end]);
  }
  return out;
}
